import { useMemo, useState } from 'react';

export type UserStatus = 'active' | 'disabled';

export interface UserRow {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
}

interface UsersTableProps {
  users: UserRow[];
  pageSize?: number;
}

const STATUS_LABEL: Record<UserStatus, string> = {
  active: 'Активен',
  disabled: 'Отключён',
};

const STATUS_BADGE_CLASS: Record<UserStatus, string> = {
  active: 'jx-badge jx-badge--success',
  disabled: 'jx-badge jx-badge--muted',
};

function UsersTable({ users, pageSize = 10 }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const totalPages = Math.max(1, Math.ceil(users.length / pageSize));
  const currentPage = Math.min(page, totalPages);

  const pageUsers = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return users.slice(start, start + pageSize);
  }, [users, currentPage, pageSize]);

  const goToPage = (nextPage: number) => {
    const clamped = Math.min(Math.max(nextPage, 1), totalPages);
    setPage(clamped);
  };

  const pageNumbers = Array.from({ length: totalPages }, (_, index) => index + 1);

  return (
    <div className="jx-card jx-stack jx-stack--md">
      <table className="jx-table" style={{ width: '100%' }}>
        <thead>
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody>
          {pageUsers.length === 0 ? (
            <tr>
              <td colSpan={3} className="jx-text jx-text--muted" style={{ textAlign: 'center' }}>
                Нет пользователей
              </td>
            </tr>
          ) : (
            pageUsers.map((user) => (
              <tr key={user.id}>
                <td>{user.name}</td>
                <td>{user.role}</td>
                <td>
                  <span className={STATUS_BADGE_CLASS[user.status]}>
                    {STATUS_LABEL[user.status]}
                  </span>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>

      {totalPages > 1 && (
        <nav
          className="jx-pagination"
          aria-label="Постраничная навигация по пользователям"
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: 'var(--jx-space-sm)',
          }}
        >
          <button
            type="button"
            className="jx-button jx-button--ghost"
            onClick={() => goToPage(currentPage - 1)}
            disabled={currentPage === 1}
            aria-label="Предыдущая страница"
          >
            ←
          </button>

          {pageNumbers.map((num) => (
            <button
              key={num}
              type="button"
              className={
                num === currentPage
                  ? 'jx-button jx-button--primary'
                  : 'jx-button jx-button--ghost'
              }
              aria-current={num === currentPage ? 'page' : undefined}
              onClick={() => goToPage(num)}
            >
              {num}
            </button>
          ))}

          <button
            type="button"
            className="jx-button jx-button--ghost"
            onClick={() => goToPage(currentPage + 1)}
            disabled={currentPage === totalPages}
            aria-label="Следующая страница"
          >
            →
          </button>
        </nav>
      )}
    </div>
  );
}

export default UsersTable;

